    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 4);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "A casual description of Scherezade García’s 2019 mural Blame It on the Bean: The Power of Coffee can make the work seem ______ —a painting that is housed in a coffee shop and that depicts three women drinking coffee may not sound particularly ambitious—but in fact the work is a complex, dynamic meditation on gender and the legacy of colonialism that demands serious attention."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "unassuming"}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "shrewd"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "incongruous"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "pretentious"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 5);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is adapted from Akwaeke Emezi’s 2019 novel Pet. Jam is a teenager who lives with her father, Aloe, and her mother, Bitter, who is a painter."}, {"type": "paragraph", "text": "Bitter finished the painting in the dark morning of a day—it was well past midnight when Jam heard the studio door creak open. She stared into the velvet black of her room and listened to her mother’s footsteps walking in her [mother] and Aloe’s bedroom. There was a weight thrumming through the floorboards in a low song, and that was how Jam knew the painting was done. [[0|Bitter’s feet were singing the news]]."}, {"type": "paragraph", "text": "©2019 by Akwaeke Emezi"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "It indicates that Jam is more interested in music than in art."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "It adds to the idea that Bitter’s footsteps reveal something to Jam."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "It indicates that Bitter always sings when working on a painting."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "It describes Aloe’s reaction upon seeing the painting for the first time."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 6);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is from Bram Stoker’s 1911 novel The Lair of the White Worm. Adam is meeting his great-uncle Richard at a port."}, {"type": "paragraph", "text": "The meeting so auspiciously begun proceeded well. Adam, seeing that the old man was interested in the novelty of the ship, suggested that he should stay the night on board, and that he would himself be ready to start at any hour and go anywhere that the other suggested. This affectionate willingness to fall in with his own plans quite won the old man’s heart. He warmly accepted the invitation, and at once they became not only on terms of affectionate relationship, but almost like old friends."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "It states the reasons why Adam and his great-uncle Richard decide to sleep on the ship rather than finding lodging on land."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "It showcases how Adam’s flexibility and consideration strengthen his relationship with his great-uncle Richard."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "It describes why Adam and his great-uncle Richard are excited for their upcoming journey on the ship."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "It contrasts great-uncle Richard’s wary first impressions of Adam with his ultimate affection toward him."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 7);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Curious about how people visually perceive objects in their dreams, Stephen LaBerge and team recruited lucid dreamers—people aware that they’re dreaming as it’s happening—for a research study. These participants were reliably able to signal when they had entered a dream state; the team then observed participants’ eye movements as they slept. [[0|The smoothness with which participants’ eyes tracked objects in their dreams closely matched how sighted people who are awake visually track objects around them]], suggesting to the team that the brain perceives dream objects as the product of something other than pure imagination."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "To offer key evidence that undermines LaBerge and team’s initial hypothesis"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "To show the unexpected result that led LaBerge and team to change the focus of their study"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "To illustrate an important real-world implication of LaBerge and team’s main finding"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "To identify a comparable circumstance that helps justify LaBerge and team’s conclusion"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 8);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "heading", "text": "Text 1"}, {"type": "paragraph", "text": "Good art often challenges and disrupts social and aesthetic norms, but the creation of public art—paintings, sculptures, and performance pieces displayed in nonmuseum or nontheatrical public settings—typically requires broad agreement among artists, civic officials, and community members about the works’ message and artistic goals. [[0|Public art that fails to appease everyone by being sufficiently aesthetically and conceptually bland almost inevitably provokes backlash]]."}, {"type": "heading", "text": "Text 2"}, {"type": "paragraph", "text": "Public art is commonly displayed in spaces intended for purposes other than meaningful aesthetic engagement. Some critics of public art therefore note that norm-defying pieces that aren’t effectively integrated within their surroundings in a manner that primes passersby to appreciate the pieces’ merits (as is often the case) tend to be regarded more unfavorably than similarly provocative art encountered in museums is."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "By arguing that the reason members of the general public might disagree about a public artwork’s merits is unrelated to the unconventionality of its appearance and ideas"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "By agreeing with the idea that only works of art that are universally appealing are suitable for displaying in public spaces"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "By disputing the notion that civic leaders and community members are easily placated by art that is intended mainly to reinforce social norms"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "By contending that the kinds of reactions controversial public artworks often receive aren’t exclusively the result of attributes inherent in the works themselves"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 9);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The average age at which people in the United States start businesses is 35. Economist Andrés Hincapié studied why young adults are relatively less likely to start businesses and whether there are ways to increase entrepreneurship in early adulthood. Hincapié found that one impediment is lack of knowledge about the practical details of how businesses are started; he further found that simply providing young adults with good informational resources on the topic significantly alleviates this problem."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Creating social networks of young adults who are interested in starting a business"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Encouraging young adults to brainstorm business ideas"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Providing young adults with practical information about how to start a business"}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Giving young adults training opportunities at a variety of businesses"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 10);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Few animals are known to spit: among them are humans, cobras, and camels. But in January 2022 at a nature preserve in southern England, bird-watcher Clare Jacobs observed a gray seal spitting a jet of water at a white-tailed eagle flying overhead. Seals had never been seen spitting before. Biologist Sean Twiss, who studies gray seals, believes that the seal may have been attempting to scare the eagle away from a food source or that the seal may have just been playing."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Bird-watching in southern England"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "A previously unseen behavior of gray seals"}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "How white-tailed eagles defend their territory against other predators"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Differences between gray seals and white-tailed eagles"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 11);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is from Mark Haber’s 2022 novel Saint Sebastian’s Abyss. The narrator and Schmidt are both art critics."}, {"type": "paragraph", "text": "When my first wife admitted to Schmidt over dinner that she didn’t find art, painting in particular, especially compelling, Schmidt winced, set down his fork, and sighed dramatically; he then excused himself, explaining an appointment he’d forgotten about had suddenly and inexplicably been remembered, while making it abundantly clear there was no appointment at all."}, {"type": "paragraph", "text": "©2022 by Mark Haber"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Schmidt is only given to theatrical behavior when in the company of the narrator and his first wife."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Schmidt’s absentmindedness regarding his schedule is uncharacteristic of him."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Schmidt’s departure is occasioned by the resumption of a previous disagreement with the narrator’s first wife about a particular painting."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Schmidt conveys his feelings about one of his dining companions without explicitly stating them."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 12);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is from Mick Herron’s 2023 novel The Secret Hours. The narrator is describing members of a government committee."}, {"type": "paragraph", "text": "Finally, and adding much-needed gravitas, was Sir Winston Day, whose features seemed moulded to adorn a bust, or possibly a stamp, and whose forehead was so evidently bulging with grey matter that it would have been impertinent to inquire too closely into the actual achievements his half century of public service had produced. His recently published memoirs possibly cast light on this enigma, but given that such details were not provided until after the thirty-page mark, they might as well have remained state secrets."}, {"type": "paragraph", "text": "©2023 by Mick Herron"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "He has the appearance of a distinguished figure, but it is uncertain whether he has accomplished anything to earn distinction."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "He looks like a person worthy of respect, but his memoirs reveal that some of his actions were dishonorable."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "He would be a celebrated public figure if his achievements did not have to be kept secret."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "He has maintained a modest profile even though he has served the public capably for many years."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 13);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Studies of ocean wave breaking have predominantly focused on traveling waves (those propagating along the horizontal plane), so Mark McAllister et al. utilized a circular wave tank to produce and study spike waves, axisymmetric standing waves that can erupt vertically when traveling waves propagating in opposing directions intersect. Traveling waves break when wave steepness (height-to-length ratio) passes a critical threshold; breaking thus constrains wave height. McAllister et al. found that spike waves can exceed that constraint, as other factors than just steepness (e.g., jet stability and cavity shape) mediate spike-wave breaking."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Previous studies have suggested that steepness mediates breaking in traveling waves, but the study by McAllister et al. shows that jet stability and cavity shape may also influence breaking in such waves."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "The process of breaking limits the height of traveling waves, but the study by McAllister et al. suggests that spike waves can exceed those limits if their height-to-length ratio reaches a critical threshold."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "McAllister et al. suggest that spike waves can form when traveling waves propagating in opposing directions intersect and that spike waves tend to be higher than traveling waves."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "The study by McAllister et al. suggests that when traveling waves intersect in specific ways, the resulting wave may be higher than would be expected based on the properties of traveling waves."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 14);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-11/rw-m1-q15.png", "alt": "Table or graph for this question", "width": 286}, {"type": "paragraph", "text": "A team of researchers used bacteria to create a biofuel (a renewable fuel produced from plants, algae, or other living materials). The team called the new fuel POP biofuel. To determine how much energy is stored in POP biofuel compared to other fuels, the team calculated the fuels’ energy density, in megajoules per liter (MJ/L). The team found that the fuel with the highest energy density is ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "jet fuel."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "POP biofuel."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "ethanol."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "gasoline."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 15);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Founded in 1965 and originally established as a cultural extension of the United Farm Workers—a union representing many Mexican American agricultural workers at the time—the theater troupe El Teatro Campesino has achieved recognition as a source of inspiration for subsequent Chicano theater companies and as a contributor to the dramatic arts. In an article about the company, a theater historian posits that a significant stylistic influence on El Teatro’s early performances was the audience-mediated slapstick comedy of carpa theater, vaudeville-style shows popular in Mexico and the US Southwest in the 1920s and ’30s."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "“The company presented actos, short comedy sketches, that often relied on exaggerated physical humor to groups of agricultural workers, whose reactions—enthusiastic cheers of appreciation and, occasionally, loud boos of disapproval—promoted improvisation.”"}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "“The company was focused on the reality of the present situation and discovered that humor was often found in that reality; consequently, comedy became a tool to convey social critique while entertaining and inspiring audiences.”"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "“The company relied heavily on satire, humor, and references to contemporary popular culture as well as a make-do aesthetic—often referred to as rasquache—that reflected not only the troupe’s limited financial resources but also its sociopolitical message.”"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "“The members of the company, which in addition to founder Luis Valdez consisted entirely of nonprofessional actors, traveled into farm fields, where they, with minimal props and costumes, performed comedy in the form of brief humorous vignettes.”"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 16);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Researchers Eugeni Vidal-Tortosa and Robin Lovelace looked at the relationship between street lighting in a city and people’s willingness to ride a bicycle. Their results suggest that poor street lighting can deter new or inexperienced cyclists from riding in a city but has little effect on experienced cyclists. Therefore, increasing the number of streetlights in a city could potentially ______"}]}'::jsonb, 'source') returning id into v_stim;
