    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "decrease the number of new or inexperienced cyclists riding in the city."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "increase the number of experienced cyclists riding in the city."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "decrease the number of experienced cyclists riding in the city."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "increase the number of new or inexperienced cyclists riding in the city."}]}'::jsonb, true);
