    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["“Organ2/ASLSP (As Slow as Possible)” is a musical piece by avant-garde composer John Cage.", "A specially designed automated organ in St. Burchardi Church in Halberstadt, Germany, began playing the piece in 2001.", "It is scheduled to stop playing the piece in 2640.", "The performance will last 639 years.", "It will be the longest continuous musical performance in history."]}, {"type": "paragraph", "text": "The student wants to indicate how long John Cage’s musical piece will last."}]}'::jsonb, 'source') returning id into v_stim;
