    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "John Cage is the composer of the musical piece “Organ2/ASLSP (As Slow as Possible).”"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "“Organ2/ASLSP (As Slow as Possible)” is a musical piece currently being played in St. Burchardi Church in Halberstadt, Germany."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Lasting 639 years, John Cage’s musical piece will be the longest continuous musical performance in history."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "An organ in St. Burchardi Church in Halberstadt, Germany, began playing a musical piece by avant-garde composer John Cage."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 30);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["1914: British explorer Ernest Shackleton and a small crew embarked on an expedition to Antarctica.", "1915: Shackleton’s ship Endurance became stuck in ice before eventually breaking apart and sinking.", "1916: After more harrowing sea-ice adventures, the entire crew was rescued.", "1959: Historian Alfred Lansing wrote a book called Endurance: Shackleton’s Incredible Voyage.", "2001: Filmmaker George Butler released a documentary called The Endurance: Shackleton’s Legendary Antarctic Expedition.", "2022: The wreckage of Endurance was discovered at the bottom of Antarctica’s Weddell Sea."]}, {"type": "paragraph", "text": "The student wants to provide a historical overview of the Shackleton expedition."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Leaving in 1914 for Antarctica, Shackleton and his crew underwent many harrowing sea-ice adventures, including losing their ship in 1915, before being rescued in 1916."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "In 1914, the Shackleton expedition sailed to Antarctica, where, in 1916, they rescued the crew of a ship that had sunk, Endurance (the wreckage of which was discovered in 2022)."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Shackleton’s expedition has inspired a 1959 book, a 2001 film, and a 2022 discovery."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Alfred Lansing wrote about the history of Shackleton’s 1914–16 expedition in the book Endurance: Shackleton’s Incredible Voyage (1959); years later, in 2001, George Butler released a documentary about the expedition."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 31);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The meter of a poem is the rhythmic structure or pattern of accents in its lines.", "Alliterative meter is structured by a pattern of repeated sounds.", "Quantitative meter is structured by a pattern of long and short syllables.", "The Old English poem Widsith uses an alliterative meter.", "The Sanskrit poem Meghadūta uses a quantitative meter."]}, {"type": "paragraph", "text": "The student wants to emphasize a difference between the meters of the two poems."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The poem Widsith is written in Old English, but Meghadūta is written in Sanskrit."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Alliterative meter is a pattern of repeated sounds, but quantitative meter is a rhythmic structure or pattern of accents."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The Sanskrit poem Meghadūta uses a quantitative meter, while the meter of the Old English poem Widsith uses a pattern of long and short syllables."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "The lines of the poem Meghadūta use a pattern of long and short syllables, whereas Widsith’s lines use a pattern of repeated sounds."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 32);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Leaders of the Province of Guatemala proclaimed independence for Central America from the Spanish Empire on September 15, 1821.", "The accompanying Declaration of Independence was written by Honduran scholar and politician José Cecilio del Valle.", "The 1812 Spanish Constitution had provided some degree of independence for Central America, but it was repealed by the Spanish king in 1814.", "Valle, a loyal advisor to the Spanish Empire’s administrators in Central America, had long opposed independence.", "He changed his mind after Colonel Rafael del Riego’s 1820 revolt, which demanded the return of rights lost in 1814."]}, {"type": "paragraph", "text": "The student wants to place the 1821 Declaration of Independence in the context of Valle’s changing political beliefs."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Colonel Riego’s revolt was the inspiration that Valle, a long-standing opponent of Central American independence, needed to change his political beliefs."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Long an opponent of Central American independence, Valle changed his mind after an 1820 revolt and wrote the 1821 declaration."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "A change in Valle’s political beliefs that occurred when the Spanish king repealed the 1812 constitution led to Valle writing Central America’s Declaration of Independence."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "The writing of Central America’s Declaration of Independence may not have happened were it not for Colonel Riego’s 1820 revolt."}]}'::jsonb, false);
