    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["In a 2020 study, researchers in California investigated how many potential nesting sites female wood ducks visited during the nesting season.", "The researchers placed nest boxes throughout the survey area and tagged 138 female wood ducks with radio frequency ID trackers.", "These trackers recorded how many nest boxes each duck visited.", "67 ducks (48.5%) visited only one nest box.", "18 ducks (13.0%) visited 10 or more nest boxes.", "Younger ducks were more likely to visit multiple nest boxes."]}, {"type": "paragraph", "text": "The student wants to present the methods used in the 2020 study."}]}'::jsonb, 'source') returning id into v_stim;
