    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "By recording how many nest boxes each duck visited, the researchers discovered that only a relatively small percentage (13.0%) of the ducks visited 10 or more nest boxes."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "After tracking how many nest boxes the 138 wood ducks visited, the researchers found that the younger ducks tended to visit more nest boxes than the older ducks."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The researchers tagged 138 female wood ducks with radio frequency ID trackers and recorded how many nest boxes each duck visited during the nesting season."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "The researchers investigated each nesting site for signs that it had been visited by the female wood ducks."}]}'::jsonb, false);
