    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Modularity of mind is the notion that the mind is at least partly composed of innate neural structures (modules) that perform fast, necessary tasks.", "1983: cognitive scientist Jerry A. Fodor hypothesized that low-level cognitive systems (e.g., perception, language) are modular.", "In Fodorian modularity, high-level systems (e.g., reasoning) are not modular.", "2003: cognitive scientist Peter Carruthers proposed the massive modularity hypothesis (MMH).", "MMH expands modularity to include all cognitive systems."]}, {"type": "paragraph", "text": "The student wants to compare Fodor’s hypothesis with Carruthers’s."}]}'::jsonb, 'source') returning id into v_stim;
